    static final int MAX = 5100;

    static long[] fact = new long[MAX];
    static long[] invFact = new long[MAX];

    static long powMod(long a, long b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        return res;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MAX; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[MAX - 1] = powMod(fact[MAX - 1], MOD - 2);
        for (int i = MAX - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;
    }

    static long C(int n, int k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    // Number of non-negative integer solutions to x1+...+xn = sum with each xi <= maxVal
    static long boundedCount(int n, int sum, int maxVal) {
        if (sum < 0) return 0;
        long res = 0;
        for (int k = 0; k <= n && k * (maxVal + 1) <= sum; k++) {
            long term = C(n, k) * C(sum - k * (maxVal + 1) + n - 1, n - 1) % MOD;
            if (k % 2 == 0) res = (res + term) % MOD;
            else res = (res - term + MOD) % MOD;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int p = Integer.parseInt(parts[0]);
        int s = Integer.parseInt(parts[1]);
        int r = Integer.parseInt(parts[2]);

        precompute();

        long total = 0;
        long win = 0;

        // Iterate over Hasan's score a1 from r to s
        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            int n = p - 1;

            // Total ways for remaining players
            long ways = C(rem + n - 1, n - 1);
            total = (total + ways) % MOD;

            // Ways where all other players have score < a1 (Hasan strictly wins)
            long strict = boundedCount(n, rem, a1 - 1);
            win = (win + strict) % MOD;

            // Ways where at least one other player has score >= a1
            long tieOrMore = (ways - strict + MOD) % MOD;

            // Among these, count cases where max of others == a1 (tie)
            // Others have max exactly a1: all <= a1 and at least one == a1
            long allLeqA1 = boundedCount(n, rem, a1);
            long allLeqA1m1 = boundedCount(n, rem, a1 - 1);
            long maxEqA1 = (allLeqA1 - allLeqA1m1 + MOD) % MOD;

            // For ties, probability of winning is 1/(count of top scorers)
            // Top scorers = 1 (Hasan) + number of others with score == a1
            // We need to sum over all distributions where max(others) == a1:
            //   sum_{k=0}^{n} [ways with exactly k others at a1 and rest < a1] * 1/(k+1)
            // This is complex, so we compute it directly:
            // For each k from 0 to n: choose k players to have a1, rest have < a1 and sum = rem - k*a1
            long tieWin = 0;
            for (int k = 0; k <= n; k++) {
                int remSum = rem - k * a1;
                if (remSum < 0) break;
                long waysRest = boundedCount(n - k, remSum, a1 - 1);
                long chooseK = C(n, k);
                long prob = powMod(k + 1, MOD - 2); // 1/(k+1)
                tieWin = (tieWin + chooseK * waysRest % MOD * prob) % MOD;
            }
            win = (win + tieWin) % MOD;
        }

        long invTotal = powMod(total, MOD - 2);
        long ans = win * invTotal % MOD;
        System.out.println(ans);
    }
