import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;
    static int[][] C;
    static int[][] dp;
    static int[][] ndp;

    static void initC(int n) {
        C = new int[n+1][n+1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
            }
        }
    }

    static int inv(int x) {
        return pow(x, MOD-2);
    }

    static int pow(long x, long n) {
        long res = 1;
        while (n > 0) {
            if ((n & 1) == 1) res = res * x % MOD;
            x = x * x % MOD;
            n >>= 1;
        }
        return (int)res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int p = Integer.parseInt(parts[0]);
        int s = Integer.parseInt(parts[1]);
        int r = Integer.parseInt(parts[2]);

        initC(s + p);

        long total = 0;
        long win = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            if (rem < 0) break;

            // Count total ways for remaining p-1 players to sum to rem
            long ways = combWithRepetition(p-1, rem);
            total = (total + ways) % MOD;

            // Count ways where all other players have score <= a1 - 1
            // i.e., strictly less than a1
            long lose = 0;
            for (int k = 0; k <= p-1; k++) {
                // Choose k players to have score >= a1
                // Remaining p-1-k players have score 0..a1-1
                // Sum of k players >= a1, remaining sum to rem - k*a1
                // But we want all others < a1, so this is the complement
                // Actually we want to count ways where max(other) < a1
                // Use inclusion-exclusion
                // Number of ways where at least k specific players have score >= a1
                // is C(p-1, k) * combWithRepetition(p-1, rem - k*a1)
                // But we want max < a1, so use inclusion-exclusion
                // Actually, let's directly compute the number of ways where all others < a1
                // This is the coefficient of x^rem in (1 + x + ... + x^(a1-1))^(p-1)
                // = (1 - x^a1)^(p-1) / (1-x)^(p-1)
                // Using inclusion-exclusion:
                // sum_{k=0}^{p-1} C(p-1, k) * (-1)^k * combWithRepetition(p-1, rem - k*a1)
                // But rem - k*a1 must be >= 0
                if (rem - k * a1 < 0) break;
                long term = (long)C[p-1][k] * combWithRepetition(p-1, rem - k * a1) % MOD;
                if (k % 2 == 1) {
                    lose = (lose - term + MOD) % MOD;
                } else {
                    lose = (lose + term) % MOD;
                }
            }

            // Ways where Hasan wins = ways - lose (where lose means some other player >= a1)
            // But if some other player == a1, it's a tie, and Hasan wins with prob 1/(number of top scorers)
            // This is more complex. Let me reconsider.

            // Actually, let's think differently.
            // Hasan wins if:
            // 1. All others < a1: probability 1
            // 2. Some others == a1 and rest < a1: probability 1/(1 + count of others with a1)
            // 3. Some others > a1: probability 0

            // This is complex. Let me use a different approach.
            // For each a1, compute:
            // - ways where max(other) < a1: contributes ways * 1
            // - ways where max(other) == a1: contributes ways * 1/(1+t) where t is count of others with a1
            // - ways where max(other) > a1: contributes 0

            // This requires knowing the distribution of how many others have exactly a1
            // when max is exactly a1.

            // Alternative: compute for each a1, the number of ways where Hasan is the unique max,
            // plus the expected contribution when there are ties.

            // Let's compute:
            // f(a1) = number of ways others sum to rem with all < a1
            // g(a1) = number of ways others sum to rem with max == a1
            // For g, we need to consider how many have exactly a1

            // Actually, let's compute the probability directly.
            // P(Hasan wins | a1) = P(all others < a1) + sum_{t>=1} P(exactly t others have a1, rest < a1) * 1/(1+t)

            // Let's compute this using generating functions.
            // Let h(x) = (1 + x + ... + x^(a1-1)) = (1-x^a1)/(1-x)
            // We want coefficient of x^rem in:
            // h(x)^(p-1) * 1  [all < a1, prob 1]
            // + sum_{t=1}^{p-1} C(p-1, t) * x^(t*a1) * h(x)^(p-1-t) * 1/(1+t)
            //   [exactly t others have a1, rest < a1]

            // This is getting complex. Let me just compute it with DP.

            // DP approach:
            // dp[i][j] = number of ways to assign scores to first i other players, sum = j, all < a1
            // Then for the tie case, we need to track how many have exactly a1

            // Let's use a 3D DP: dp[i][j][k] = ways for first i players, sum j, k players with score a1
            // This might be too slow.

            // Actually, let's think about it more carefully.
            // We can compute:
            // A = number of ways all others < a1 (sum = rem)
            // B_t = number of ways exactly t others have score a1, rest < a1 (sum = rem)
            // Then P(win | a1) = (A + sum_t B_t / (1+t)) / total_ways_for_this_a1

            // But total_ways_for_this_a1 = combWithRepetition(p-1, rem)

            // Let's compute A and B_t using DP.
            // dp[i][j] = ways for first i players, sum j, all scores in [0, a1-1]
            // This gives A = dp[p-1][rem]

            // For B_t, we need to track how many have exactly a1.
            // dp2[i][j][k] = ways for first i players, sum j, k players with score exactly a1, rest in [0, a1-1]
            // B_t = dp2[p-1][rem][t]

            // Let's compute this.
            // dp[i][j] for all < a1
            // dp2[i][j][k] for exactly k with a1

            // Actually, we can combine:
            // dp[i][j][k] = ways for first i players, sum j, k players with score exactly a1, rest in [0, a1-1]
            // Transition: for player i+1, either score a1 (k increases by 1, j increases by a1) or score in [0, a1-1] (k stays, j increases by score)

            // This is O(p * s * p * a1) which might be too slow.
            // But a1 <= s <= 5000, p <= 100, so O(100 * 5000 * 100 * 5000) is too much.

            // Let me think of a better way.
            // We can separate: first choose which t players have score a1, then the rest have score in [0, a1-1] summing to rem - t*a1.
            // B_t = C(p-1, t) * coeff of x^(rem - t*a1) in h(x)^(p-1-t)
            // where h(x) = 1 + x + ... + x^(a1-1)

            // And A = coeff of x^rem in h(x)^(p-1)

            // So:
            // P(win | a1) = (A + sum_{t=1}^{p-1} B_t / (1+t)) / total
            // = (A + sum_{t=1}^{p-1} C(p-1,t) * coeff(x^(rem-t*a1), h(x)^(p-1-t)) / (1+t)) / total

            // We need to compute coefficients of h(x)^n for various n.
            // h(x) = (1 - x^a1) / (1 - x)
            // h(x)^n = (1-x^a1)^n * (1-x)^(-n)
            // coeff of x^m in h(x)^n = sum_{k=0}^{min(n, m/a1)} C(n,k) * (-1)^k * C(m - k*a1 + n - 1, n - 1)

            // This is computable!

            long A = coeffH(rem, p-1, a1);
            long tieContrib = 0;
            for (int t = 1; t <= p-1; t++) {
                int rem2 = rem - t * a1;
                if (rem2 < 0) break;
                long Bt = (long)C[p-1][t] * coeffH(rem2, p-1-t, a1) % MOD;
                tieContrib = (tieContrib + Bt * inv(t + 1)) % MOD;
            }

            long winForA1 = (A + tieContrib) % MOD;
            win = (win + winForA1) % MOD;
        }

        long ans = win * inv(total) % MOD;
        System.out.println(ans);
    }

    // Coefficient of x^rem in h(x)^n where h(x) = 1 + x + ... + x^(a1-1)
    static long coeffH(int rem, int n, int a1) {
        if (n == 0) {
            return rem == 0 ? 1 : 0;
        }
        long res = 0;
        for (int k = 0; k <= n && k * a1 <= rem; k++) {
            long term = (long)C[n][k] * C[rem - k * a1 + n - 1][n - 1] % MOD;
            if (k % 2 == 1) {
                res = (res - term + MOD) % MOD;
            } else {
                res = (res + term) % MOD;
            }
        }
        return res;
    }

    // Number of ways to distribute rem among n players (each >= 0)
    static long combWithRepetition(int n, int rem) {
        if (n == 0) return rem == 0 ? 1 : 0;
        if (rem < 0) return 0;
        return C[rem + n - 1][n - 1];
    }
}
