public class Main {
    static final int MOD = 998244353;
    static final int MAX = 5100;

    static long[] fact = new long[MAX];
    static long[] ifact = new long[MAX];

    static long powmod(long a, long n) {
        long res = 1;
        a %= MOD;
        while (n > 0) {
            if ((n & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            n >>= 1;
        }
        return res;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MAX; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        ifact[MAX - 1] = powmod(fact[MAX - 1], MOD - 2);
        for (int i = MAX - 2; i >= 0; i--) {
            ifact[i] = ifact[i + 1] * (i + 1) % MOD;
        }
    }

    static long C(int n, int k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * ifact[k] % MOD * ifact[n - k] % MOD;
    }

    // Number of non-negative integer solutions to x1 + x2 + ... + xn = s
    static long ways(int n, int s) {
        if (s < 0) return 0;
        if (n == 0) return s == 0 ? 1 : 0;
        return C(s + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        precompute();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int s = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        long total = ways(p, s - r); // total states with a1 >= r

        long win = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            // Count states where all other p-1 players have <= a1 - 1
            long allLess = 0;
            for (int k = 0; k <= p - 1; k++) {
                int t = rem - k * a1;
                if (t < 0) break;
                long term = C(p - 1, k) * ways(p - 1, t) % MOD;
                if ((k & 1) == 0) allLess = (allLess + term) % MOD;
                else allLess = (allLess - term + MOD) % MOD;
            }

            // Count states where at least one other player has exactly a1 (i.e., all <= a1 minus all <= a1-1)
            long exactlyA1 = (ways(p - 1, rem) - allLess + MOD) % MOD;

            // Probability of winning when a1 is the max:
            // If all others < a1: 1
            // If some others == a1: 1/(count of max)
            // We need to compute the average over all states with this a1.
            // For states where all others < a1: contribute allLess * 1
            // For states where some others == a1: contribute exactlyA1 * (1 / (number of players with a1 + 1))
            // But this is complex. Instead, we use the formula:
            // For each state with a1, the probability of winning is:
            //   1 if all others < a1
            //   1/(m+1) if m others == a1 (m >= 1)
            // So we need to compute sum over states of (1/(m+1)) where m is the number of others equal to a1.

            // Alternative approach:
            // Let f(a1) = number of states where a1 is the max and exactly m others have a1.
            // Then the contribution is sum_{m=0}^{p-1} f(a1, m) * 1/(m+1)
            // This is equivalent to:
            //   allLess * 1 + sum_{m=1}^{p-1} f(a1, m) * 1/(m+1)
            // But computing f(a1, m) is complex.

            // Better approach:
            // The total contribution for a1 is:
            //   allLess * 1 + (exactlyA1 - f(a1, 0)) * ... no.
            // Let's think differently.
            // The number of states where a1 is the max and exactly m others have a1:
            //   Choose m players from p-1 to have a1: C(p-1, m)
            //   The remaining p-1-m players have <= a1-1 and sum to rem - m*a1
            //   So f(a1, m) = C(p-1, m) * ways(p-1-m, rem - m*a1)
            //   But we need to ensure rem - m*a1 >= 0 and the remaining players have <= a1-1.
