        if (total == 0) {
            System.out.println(0);
            return;
        }

        long inv_total = modInverse(total, MOD);
        long ans = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            if (rem < 0) continue;

            long ways_leq = comb(rem + p - 2, p - 2);
            long ways_less = 0;

            if (a1 > 0) {
                int max_per = a1 - 1;
                if (max_per >= 0) {
                    ways_less = comb(rem + p - 2, p - 2);
                    for (int k = 1; ; k++) {
