                        } else {
                            ways_less = (ways_less + c) % MOD;
                        }
                    }
                }
            }

            long ways_eq = (ways_leq - ways_less + MOD) % MOD;
            long prob = (ways_less + ways_eq * modInverse(2, MOD)) % MOD;
            ans = (ans + prob) % MOD;
        }

        ans = ans * inv_total % MOD;
