public class Main {
    static final int MOD = 998244353;
    static final int MAX_S = 5000;
    static final int MAX_P = 100;

    static long[][] C = new long[MAX_S + 1][MAX_S + 1];
    static long[] fact = new long[MAX_S + 1];
    static long[] invFact = new long[MAX_S + 1];

    static void precompute() {
        // Precompute combinations C(n, k) mod MOD
        for (int n = 0; n <= MAX_S; n++) {
            C[n][0] = 1;
            for (int k = 1; k <= n; k++) {
                C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD;
            }
        }

        // Precompute factorials and inverse factorials mod MOD
        fact[0] = 1;
        for (int i = 1; i <= MAX_S; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[MAX_S] = BigInteger.valueOf(fact[MAX_S]).modInverse(BigInteger.valueOf(MOD)).longValue();
        for (int i = MAX_S - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
    }

    // Compute number of ways to distribute 'sum' into 'p' non-negative integers where each is <= 'max'
    static long ways(int sum, int p, int max) {
        if (sum < 0) return 0;
        if (p == 0) return sum == 0 ? 1 : 0;
        if (max < 0) return 0;

        long res = 0;
        for (int k = 0; k <= p && k * (max + 1) <= sum; k++) {
            long term = C[p][k] * C[sum - k * (max + 1) + p - 1][p - 1] % MOD;
            if (k % 2 == 0) {
                res = (res + term) % MOD;
            } else {
                res = (res - term + MOD) % MOD;
            }
        }
        return res;
    }

    // Compute number of ways to distribute 'sum' into 'p' non-negative integers where each is <= 'max'
    // and at least one is exactly 'max'
    static long waysWithMax(int sum, int p, int max) {
        if (sum < 0) return 0;
        if (p == 0) return sum == 0 ? 1 : 0;
        if (max < 0) return 0;

        // Total ways with all <= max
        long total = ways(sum, p, max);
        // Subtract ways with all <= max-1
        long withoutMax = ways(sum, p, max - 1);
        return (total - withoutMax + MOD) % MOD;
    }

    public static void main(String[] args) throws Exception {
        precompute();

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int s = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        // Total valid states: a1 >= r, sum = s, a_i >= 0
        // a1' = a1 - r, a1' >= 0, sum of a1' + a2 + ... + ap = s - r
        long totalStates = ways(s - r, p, s - r); // a1' can be up to s-r, others up to s-r

        long winningStates = 0;

        // Case 1: a1 > all others (a1 is strictly the maximum)
        // a1 = r + a1', a1' >= 0, sum of a1' + a2 + ... + ap = s - r
        // We need a1 > a_i for all i >= 2
        // a1 = r + a1', so r + a1' > a_i for all i >= 2
        // a_i <= r + a1' - 1
        // Sum: a1' + a2 + ... + ap = s - r
        // a_i <= r + a1' - 1 for i >= 2
        // Let's iterate over a1' (which is a1 - r)
        // a1' ranges from 0 to s - r
        // For each a1', we need a2 + ... + ap = s - r - a1'
        // and each a_i <= r + a1' - 1 (for i >= 2)
        // Number of ways = ways(s - r - a1', p - 1, r + a1' - 1)
        for (int a1Prime = 0; a1Prime <= s - r; a1Prime++) {
            int remaining = s - r - a1Prime;
            int maxOther = r + a1Prime - 1;
            if (maxOther < 0) continue;
            long w = ways(remaining, p - 1, maxOther);
            winningStates = (winningStates + w) % MOD;
        }

        // Case 2: a1 is tied with some others at the maximum
        // a1 = max, and some other players also have a1
        // Probability of winning = 1 / (number of players with max score)
        // We need to count, for each possible max value m:
        // - a1 = m (so m >= r)
        // - At least one other player has score m
        // - All players have score <= m
        // - Sum = s
        // For each such configuration, the probability of Hasan winning is 1 / (number of players with score m)
        // This is complex, so we use inclusion-exclusion or direct counting

        // Alternative approach: for each possible value of a1 (from r to s):
        // Count the number of ways where a1 is the unique maximum -> contributes 1 * count
        // Count the number of ways where a1 is tied with k others -> contributes (1/(k+1)) * count
        // This is still complex

        // Let's use a different approach:
        // For each possible a1 value (from r to s):
        // Let m = a1
        // Count ways where all other players have score <= m
        // Subtract ways where all other players have score <= m-1 (to ensure at least one has score m, or a1 is the unique max)
        // Actually, we need:
        // - Ways where a1 = m and all others <= m: ways(s - m, p - 1, m)
        // - Ways where a1 = m and all others <= m-1: ways(s - m, p - 1, m - 1)
        // The difference gives ways where a1 = m and at least one other has score m

        // For the unique max case (a1 > all others):
        // a1 = m, all others <= m - 1
        // ways(s - m, p - 1, m - 1)

        // For the tied case (a1 = m, at least one other = m):
        // ways(s - m, p - 1, m) - ways(s - m, p - 1, m - 1)
        // But we need to weight by 1/(number of players with score m)

        // This is getting complex. Let's use the direct formula:
        // P(win) = sum over all valid states of (1 / count_of_max_players) / total_states
        // = (1 / total_states) * sum over all valid states of (1 / count_of_max_players)

        // For each a1 from r to s:
        // Let m = a1
        // remaining = s - m
        // We need to distribute 'remaining' among p-1 players, each >= 0 and <= m
        // For each such distribution, let k = number of players (among p-1) with score m
        // If k = 0: Hasan wins with probability 1
        // If k >= 1: Hasan wins with probability 1/(k+1)

        // So for each a1 = m:
        // contribution = sum over all distributions of remaining into p-1 parts (each <= m) of:
        //   1 if no other player has score m
        //   1/(k+1) if k other players have score m

        // This is equivalent to:
        // contribution = ways(remaining, p-1, m-1) * 1  (no other player has score m)
        //              + sum_{k=1}^{p-1} (number of ways with exactly k others having score m) * 1/(k+1)

        // Number of ways with exactly k others having score m:
        // Choose k players from p-1: C(p-1, k)
        // Those k players have score m, so they contribute k*m to the sum
        // Remaining sum = remaining - k*m, distributed among (p-1-k) players, each <= m-1
        // = C(p-1, k) * ways(remaining - k*m, p-1-k, m-1)

        // So contribution for a1 = m:
        // = ways(remaining, p-1, m-1) + sum_{k=1}^{p-1} C(p-1, k) * ways(remaining - k*m, p-1-k, m-1) / (k+1)

        // This involves division by (k+1), which we handle with modular inverse

        // Let's compute this
        for (int m = r; m <= s; m++) {
            int remaining = s - m;
            if (remaining < 0) break;

            // Case: no other player has score m (Hasan is unique max)
            long uniqueMax = ways(remaining, p - 1, m - 1);
            winningStates = (winningStates + uniqueMax) % MOD;

            // Case: k other players have score m (tied with Hasan)
            for (int k = 1; k <= p - 1; k++) {
                if (k * m > remaining) break;
                long chooseK = C[p - 1][k];
                long w = ways(remaining - k * m, p - 1 - k, m - 1);
                long invKPlus1 = BigInteger.valueOf(k + 1).modInverse(BigInteger.valueOf(MOD)).longValue();
                long contrib = chooseK * w % MOD * invKPlus1 % MOD;
                winningStates = (winningStates + contrib) % MOD;
            }
        }

        // Probability = winningStates / totalStates
        long invTotal = BigInteger.valueOf(totalStates).modInverse(BigInteger.valueOf(MOD)).longValue();
        long result = winningStates * invTotal % MOD;
        System.out.println(result);
    }
}
