        for (int i = MAX-2; i >= 0; i--) ifact[i] = ifact[i+1] * (i+1) % MOD;
        inv[1] = 1;
        for (int i = 2; i < MAX; i++) inv[i] = MOD - MOD/i * inv[MOD%i] % MOD;
    }

    static long C(int n, int k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * ifact[k] % MOD * ifact[n-k] % MOD;
    }

    // Number of ways to distribute 'sum' into 'cnt' non-negative integers, each <= 'maxVal'
    static long bounded(int cnt, int sum, int maxVal) {
        if (sum < 0) return 0;
        long res = 0;
        for (int k = 0; k <= cnt && k*(maxVal+1) <= sum; k++) {
            long term = C(cnt, k) * C(sum - k*(maxVal+1) + cnt - 1, cnt - 1) % MOD;
            if (k % 2 == 0) res = (res + term) % MOD;
            else res = (res - term + MOD) % MOD;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
