        long win = 0;
        // For each possible Hasan score a1 = r, r+1, ..., s
        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            // Count sequences where a2, ..., ap are all <= a1 - 1 (Hasan strictly wins)
            long strict = bounded(p - 1, rem, a1 - 1);
            // Count sequences where max(a2..ap) == a1 (tie at top, Hasan is among top, prob 1/(count of top))
            // We need to count sequences where max(a2..ap) == a1, and then for each such sequence,
            // the probability Hasan wins is 1/(number of players with score a1)
            // This is complex, so we use inclusion-exclusion over the number of players tied with Hasan

            // Let's compute: for each k (number of other players with score == a1), 
            // count sequences where exactly k of a2..ap equal a1, and the rest are <= a1-1
            // Then Hasan's winning prob for that case is 1/(k+1)

            // But this is still complex. Alternative approach:
            // P(Hasan wins) = sum over all valid sequences of [1 / (number of players with max score)]
            // where the max score is achieved by Hasan (i.e., a1 is the max)

            // Let's think differently:
            // For a fixed a1, we want to count:
            // sum over all (a2..ap) with sum = rem, of [1 / (1 + count of i in 2..p with ai == a1)] if a1 >= max(ai)
            // This is hard to compute directly.

            // Alternative: use the formula
            // P(win) = sum_{a1=r}^{s} [ (ways where a1 is strictly max) + (ways where a1 is tied max) * 1/(tie count) ] / total

            // For "a1 is strictly max": all ai < a1 for i >= 2
            long waysStrict = bounded(p - 1, rem, a1 - 1);

            // For "a1 is tied max": at least one ai == a1, and all ai <= a1
            // We need to count, for each such sequence, 1/(number of players with score a1)
            // This equals: sum over sequences where max(ai) = a1, of 1/(1 + count of ai == a1)

            // Let's compute this using generating functions / inclusion
            // For each subset S of {2..p} that must have ai == a1, and the rest have ai <= a1-1:
            // But we need to avoid overcounting. 

            // Actually, let's use the following identity:
            // sum over sequences with max = a1 of 1/(1 + count of a1's)
            // = sum over sequences with all ai <= a1 and at least one ai == a1, of 1/(1 + count of a1's)

            // Let f(k) = number of sequences where exactly k of a2..ap have ai == a1, rest <= a1-1, sum = rem
            // Then contribution = sum_k f(k) * 1/(k+1)

            // f(k) = C(p-1, k) * [number of ways to distribute rem - k*a1 into p-1-k parts each <= a1-1]
            // = C(p-1, k) * bounded(p-1-k, rem - k*a1, a1-1)

            long tieContribution = 0;
            for (int k = 1; k <= p - 1; k++) {
                if (k * a1 > rem) break;
                long f = C(p - 1, k) * bounded(p - 1 - k, rem - k * a1, a1 - 1) % MOD;
                // contribution is f * 1/(k+1)
                tieContribution = (tieContribution + f * inv[k + 1]) % MOD;
            }

            win = (win + waysStrict + tieContribution) % MOD;
        }

        long ans = win * BigInteger.valueOf(total).modPow(BigInteger.valueOf(MOD-2), BigInteger.valueOf(MOD)).longValue() % MOD;
        System.out.println(ans);
    }
