public class Main {
    static final int MOD = 998244353;
    static final int MAX = 5010;

    static long[] fact = new long[MAX];
    static long[] inv_fact = new long[MAX];

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MAX; i++) fact[i] = fact[i - 1] * i % MOD;
        inv_fact[MAX - 1] = modPow(fact[MAX - 1], MOD - 2);
        for (int i = MAX - 2; i >= 0; i--) inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }

    static long comb(int n, int k) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
    }

    // Number of ways to distribute `sum` among `players` players where each player gets at least 0
    static long ways(int players, int sum) {
        if (sum < 0) return 0;
        return comb(sum + players - 1, players - 1);
    }

    // Number of ways where each of `players` players gets at least `min`
    static long waysWithMin(int players, int sum, int min) {
        if (min < 0) return ways(players, sum);
        return ways(players, sum - players * min);
    }

    public static void main(String[] args) throws IOException {
        precompute();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int p = Integer.parseInt(parts[0]);
        int s = Integer.parseInt(parts[1]);
        int r = Integer.parseInt(parts[2]);

        long total = 0;
        long win = 0;

        // Iterate over Hasan's score a1 from r to s
        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            int otherPlayers = p - 1;

            // Total ways for this a1
            long t = ways(otherPlayers, rem);
            total = (total + t) % MOD;

            // Winning cases: all other players have score < a1
            // This means each of the other players has score in [0, a1-1]
            // Use inclusion-exclusion to count distributions where all <= a1 - 1
            long w = 0;
            for (int k = 0; k <= otherPlayers; k++) {
                // Choose k players to have >= a1, rest have any
                long c = comb(otherPlayers, k);
                int newSum = rem - k * a1;
                long waysRest = ways(otherPlayers, newSum);
                if (k % 2 == 0) {
                    w = (w + c * waysRest) % MOD;
                } else {
                    w = (w - c * waysRest % MOD + MOD) % MOD;
                }
            }

            // Now, among the cases where max(other scores) == a1, Hasan wins with probability 1/(number of top scorers)
            // Number of top scorers = 1 + (number of other players with score == a1)
            // We need to subtract cases where some others have score == a1 and add the fractional contribution

            // Let's compute:
            // - ways where all others < a1: Hasan wins for sure (prob 1)
            // - ways where some others == a1: Hasan wins with prob 1/(1 + count of others with a1)

            // First, w is the number of ways where all others < a1 (Hasan wins with prob 1)
            win = (win + w) % MOD;

            // Now handle cases where at least one other player has score == a1
            // We need to count, for each subset of other players with score == a1, the number of ways
            // and the probability contribution

            // Let m = number of other players with score exactly a1
            // For each m from 1 to otherPlayers:
            //   Choose m players to have score a1
            //   Remaining (otherPlayers - m) players have score < a1 (i.e., in [0, a1-1])
            //   Sum of remaining = rem - m * a1
            //   Number of ways = C(otherPlayers, m) * waysWithMax(otherPlayers - m, rem - m*a1, a1 - 1)
            //   Probability contribution = 1/(1 + m) * number of ways

            for (int m = 1; m <= otherPlayers; m++) {
                int sumLeft = rem - m * a1;
                if (sumLeft < 0) break;

                // Number of ways to distribute sumLeft among (otherPlayers - m) players, each in [0, a1-1]
                long waysSub = 0;
                int playersSub = otherPlayers - m;
                for (int k = 0; k <= playersSub; k++) {
                    long c = comb(playersSub, k);
                    int newSum = sumLeft - k * a1;
                    long waysRest = ways(playersSub, newSum);
                    if (k % 2 == 0) {
                        waysSub = (waysSub + c * waysRest) % MOD;
                    } else {
                        waysSub = (waysSub - c * waysRest % MOD + MOD) % MOD;
                    }
                }

                long c = comb(otherPlayers, m);
                long contrib = c * waysSub % MOD;
                // Probability = 1/(1+m), so contribution to win = contrib * inv(1+m)
                long invM = modPow(m + 1, MOD - 2);
                win = (win + contrib * invM) % MOD;
            }
        }

        // Probability = win / total
        long invTotal = modPow(total, MOD - 2);
        long ans = win * invTotal % MOD;
        System.out.println(ans);
    }
}
